#![cfg(test)]

use soroban_sdk::{testutils::Address as _, Address, Bytes, Env, String, Symbol, Vec};

use crate::AdvancedPoolHooksExtractorContract;
use common_error::CCIPError;
use common_interfaces::policy_engine::{Parameter, Payload, PolicyData, PolicyValue};
use common_interfaces::pool_hooks::{PoolHooksPayloadData, PostflightPayload, PreflightPayload};
use common_interfaces::token_pool::{LockOrBurnIn, ReleaseOrMintIn};

// Generated by `#[contractimpl]` above.
use crate::AdvancedPoolHooksExtractorContractClient;

const REMOTE_CHAIN: u64 = 5009297550715157269;

fn env_and_client() -> (Env, AdvancedPoolHooksExtractorContractClient<'static>) {
    let env = Env::default();
    env.mock_all_auths_allowing_non_root_auth();
    let id = env.register(AdvancedPoolHooksExtractorContract, ());
    // Build the client (borrowing `env`) before moving `env` into the tuple —
    // `Env` is not `Copy`.
    let client = AdvancedPoolHooksExtractorContractClient::new(&env, &id);
    (env, client)
}

fn lock_or_burn(env: &Env, sender: Address, receiver: Bytes) -> LockOrBurnIn {
    LockOrBurnIn {
        receiver,
        remote_chain_selector: REMOTE_CHAIN,
        original_sender: sender,
        amount: 1_000,
        local_token: Address::generate(env),
    }
}

fn release_or_mint(env: &Env, sender: Bytes, receiver: Address) -> ReleaseOrMintIn {
    ReleaseOrMintIn {
        original_sender: sender,
        remote_chain_selector: REMOTE_CHAIN,
        receiver,
        amount: 7_777, // source-denominated amount
        local_token: Address::generate(env),
        source_pool_address: Bytes::from_slice(env, &[0xde, 0xad, 0xbe, 0xef]),
        source_pool_data: Bytes::from_slice(env, &[0xc0, 0xff, 0xee]),
    }
}

fn preflight_payload(env: &Env, p: PreflightPayload) -> Payload {
    Payload {
        selector: Symbol::new(env, "preflight_check"),
        sender: Address::generate(env),
        data: PolicyData::PoolHooks(PoolHooksPayloadData::Preflight(p)),
        context: Bytes::from_slice(env, &[0xaa]), // skipped, like EVM
    }
}

fn postflight_payload(env: &Env, p: PostflightPayload) -> Payload {
    Payload {
        selector: Symbol::new(env, "postflight_check"),
        sender: Address::generate(env),
        data: PolicyData::PoolHooks(PoolHooksPayloadData::Postflight(p)),
        context: Bytes::from_slice(env, &[0xbb]), // skipped, like EVM
    }
}

/// Finds the first parameter with the given name, panicking if absent.
/// Soroban `Vec::iter` yields owned values, so this returns an owned `Parameter`.
fn param(params: &Vec<Parameter>, env: &Env, name: &str) -> Parameter {
    let key = Symbol::new(env, name);
    params
        .iter()
        .find(|p| p.name == key)
        .unwrap_or_else(|| panic!("missing parameter `{name}`"))
}

#[test]
fn test_type_and_version() {
    let (env, client) = env_and_client();
    assert_eq!(
        client.type_and_version(),
        String::from_str(&env, "AdvancedPoolHooksExtractor 2.0.0")
    );
}

#[test]
fn test_preflight_extracts_seven_named_params() {
    let (env, client) = env_and_client();
    let sender = Address::generate(&env);
    let receiver = Bytes::from_slice(&env, &[0x01, 0x02, 0x03, 0x04]);
    let lob = lock_or_burn(&env, sender.clone(), receiver.clone());
    let payload = preflight_payload(
        &env,
        PreflightPayload {
            lock_or_burn_in: lob,
            requested_finality: 9,
            amount_post_fee: 990,
        },
    );

    let params = client.extract(&payload);
    assert_eq!(params.len(), 7, "preflight must project exactly 7 params");

    // from = originalSender (address)
    assert_eq!(
        param(&params, &env, "from").value,
        PolicyValue::Address(sender)
    );
    // to = receiver (bytes)
    assert_eq!(
        param(&params, &env, "to").value,
        PolicyValue::Bytes(receiver)
    );
    // amount = lock_or_burn_in.amount
    assert_eq!(
        param(&params, &env, "amount").value,
        PolicyValue::I128(1_000)
    );
    // amount_post_fee
    assert_eq!(
        param(&params, &env, "amount_post_fee").value,
        PolicyValue::I128(990)
    );
    // remote_chain_selector (u64)
    assert_eq!(
        param(&params, &env, "remote_chain_selector").value,
        PolicyValue::U64(REMOTE_CHAIN)
    );
    // token = localToken (address)
    assert!(matches!(
        param(&params, &env, "token").value,
        PolicyValue::Address(_)
    ));
    // requested_finality (u32)
    assert_eq!(
        param(&params, &env, "requested_finality").value,
        PolicyValue::U32(9)
    );
}

#[test]
fn test_postflight_extracts_nine_named_params() {
    let (env, client) = env_and_client();
    let sender = Bytes::from_slice(&env, &[0x05, 0x06]);
    let receiver = Address::generate(&env);
    let rom = release_or_mint(&env, sender.clone(), receiver.clone());
    let local_amount = 5_000; // the scalar minted/released locally
    let payload = postflight_payload(
        &env,
        PostflightPayload {
            release_or_mint_in: rom,
            local_amount,
            requested_finality: 12,
        },
    );

    let params = client.extract(&payload);
    assert_eq!(params.len(), 9, "postflight must project exactly 9 params");

    // from = originalSender (bytes)
    assert_eq!(
        param(&params, &env, "from").value,
        PolicyValue::Bytes(sender)
    );
    // to = receiver (address)
    assert_eq!(
        param(&params, &env, "to").value,
        PolicyValue::Address(receiver)
    );
    // amount = localAmount (the scalar), NOT release_or_mint_in.amount (7777)
    assert_eq!(
        param(&params, &env, "amount").value,
        PolicyValue::I128(local_amount)
    );
    assert_ne!(
        param(&params, &env, "amount").value,
        PolicyValue::I128(7_777),
        "amount must be local_amount, not the source-denominated amount"
    );
    // remote_chain_selector
    assert_eq!(
        param(&params, &env, "remote_chain_selector").value,
        PolicyValue::U64(REMOTE_CHAIN)
    );
    // token (address)
    assert!(matches!(
        param(&params, &env, "token").value,
        PolicyValue::Address(_)
    ));
    // requested_finality
    assert_eq!(
        param(&params, &env, "requested_finality").value,
        PolicyValue::U32(12)
    );
    // source_pool_address (bytes)
    assert_eq!(
        param(&params, &env, "source_pool_address").value,
        PolicyValue::Bytes(Bytes::from_slice(&env, &[0xde, 0xad, 0xbe, 0xef]))
    );
    // source_pool_data (bytes)
    assert_eq!(
        param(&params, &env, "source_pool_data").value,
        PolicyValue::Bytes(Bytes::from_slice(&env, &[0xc0, 0xff, 0xee]))
    );
    // source_denominated_amount = release_or_mint_in.amount (7777)
    assert_eq!(
        param(&params, &env, "source_denominated_amount").value,
        PolicyValue::I128(7_777)
    );
}

#[test]
fn test_unknown_selector_reverts_unsupported_selector() {
    let (env, client) = env_and_client();
    let lob = lock_or_burn(&env, Address::generate(&env), Bytes::new(&env));
    let mut payload = preflight_payload(
        &env,
        PreflightPayload {
            lock_or_burn_in: lob,
            requested_finality: 0,
            amount_post_fee: 0,
        },
    );
    // A selector this extractor does not handle.
    payload.selector = Symbol::new(&env, "bogus_check");

    let r = client.try_extract(&payload);
    match r {
        Ok(Ok(_)) => panic!("unknown selector must not extract"),
        // Contract error surfaces on the outer-Err side as Err(Ok(CCIPError)).
        Err(Ok(e)) => assert_eq!(e, CCIPError::UnsupportedSelector),
        Ok(Err(_)) => panic!("unexpected conversion error"),
        Err(Err(_)) => panic!("unexpected host error"),
    }
}

#[test]
fn test_selector_data_mismatch_reverts_unsupported_selector() {
    let (env, client) = env_and_client();
    let lob = lock_or_burn(&env, Address::generate(&env), Bytes::new(&env));
    // Preflight data, but the postflight selector — a malformed payload.
    let mut payload = preflight_payload(
        &env,
        PreflightPayload {
            lock_or_burn_in: lob,
            requested_finality: 0,
            amount_post_fee: 0,
        },
    );
    payload.selector = Symbol::new(&env, "postflight_check");

    let r = client.try_extract(&payload);
    match r {
        Ok(Ok(_)) => panic!("selector/data mismatch must not extract"),
        Err(Ok(e)) => assert_eq!(e, CCIPError::UnsupportedSelector),
        Ok(Err(_)) => panic!("unexpected conversion error"),
        Err(Err(_)) => panic!("unexpected host error"),
    }
}

#[test]
fn test_context_is_skipped() {
    // `context` (token_args / offchain_token_data) must never appear as a
    // parameter — EVM skips it, and so does this extractor.
    let (env, client) = env_and_client();
    let lob = lock_or_burn(&env, Address::generate(&env), Bytes::new(&env));
    let payload = preflight_payload(
        &env,
        PreflightPayload {
            lock_or_burn_in: lob,
            requested_finality: 0,
            amount_post_fee: 0,
        },
    );
    let params = client.extract(&payload);
    let no_context = !params.iter().any(|p| {
        p.name == Symbol::new(&env, "context") || p.name == Symbol::new(&env, "token_args")
    });
    assert!(no_context, "context / token_args must not be projected");
}
